import React, { useEffect, useState } from "react";
import api from "../services/api";

export default function Profile() {

  const [profile, setProfile] = useState(null);

  const [form, setForm] = useState({
    prenom: "",
    nom: "",
    email: "",
    telephone: "",
    ville: ""
  });

  const fetchProfile = async () => {
    try {
      const res = await api.get("/api/professeurs/me");
      setProfile(res.data);
    } catch (err) {
      console.error("Erreur chargement profil", err);
    }
  };

  useEffect(() => {
    fetchProfile();
  }, []);

  useEffect(() => {
    if (profile) {
      setForm({
        prenom: profile.user_prenom || "",
        nom: profile.user_nom || "",
        email: profile.email || "",
        telephone: profile.telephone || "",
        ville: profile.ville || ""
      });
    }
  }, [profile]);

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      await api.put("/api/professeurs/me", form);
      alert("Profil mis à jour !");
      fetchProfile();
    } catch (err) {
      console.error(err);
      alert("Erreur mise à jour");
    }
  };

  const inp = {
    background: "var(--surface2)",
    border: "1px solid var(--border)",
    borderRadius: 10,
    color: "var(--text)",
    padding: "10px 14px",
    fontSize: ".9rem",
    outline: "none",
    width: "100%"
  };

  return (
    <div style={{ padding: 32, maxWidth: 900, margin: "0 auto" }}>

      <h2 style={{ marginBottom: 30 }}>👤 Mon Profil</h2>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 20 }}>

        <div>
          <label>Prénom</label>
          <input
            name="prenom"
            style={inp}
            value={form.prenom}
            onChange={handleChange}
          />
        </div>

        <div>
          <label>Nom</label>
          <input
            name="nom"
            style={inp}
            value={form.nom}
            onChange={handleChange}
          />
        </div>

        <div>
          <label>Email</label>
          <input
            name="email"
            style={inp}
            value={form.email}
            disabled
          />
        </div>

        <div>
          <label>Téléphone</label>
          <input
            name="telephone"
            style={inp}
            value={form.telephone}
            onChange={handleChange}
          />
        </div>

        <div>
          <label>Ville</label>
          <select
            name="ville"
            style={inp}
            value={form.ville}
            onChange={handleChange}
          >
            <option value="Tunis">Tunis</option>
            <option value="Sfax">Sfax</option>
            <option value="Sousse">Sousse</option>
            <option value="Monastir">Monastir</option>
            <option value="Gabes">Gabes</option>
          </select>
        </div>

        <button
          type="submit"
          style={{
            background: "var(--accent)",
            color: "#fff",
            border: "none",
            padding: 12,
            borderRadius: 10,
            fontWeight: 600,
            cursor: "pointer"
          }}
        >
          Enregistrer
        </button>

      </form>

    </div>
  );
}
